"""Parsers for catalog.txt, movements.txt and orders.txt."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, Iterator, List, Tuple

SKU_RE = re.compile(r"^[A-Za-z]{2,4}-[0-9]{3}$")
PRICE_RE = re.compile(r"^[0-9]+(\.[0-9]{1,2})?$")
WHOLE_RE = re.compile(r"^[0-9]+$")
SIGNED_RE = re.compile(r"^[+-]?[0-9]+$")
DATE_RE = re.compile(r"^([0-9]{4})-([0-9]{2})-([0-9]{2})$")
ORDER_RE = re.compile(r"^[Ss][Oo]-[0-9]+$")
ORDER_LINE_RE = re.compile(r"^([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)$")
SEP_RE = re.compile(r"[ \t]+")

WS = " \t"
TAX_RATES = {
    "standard": Decimal("0.20"),
    "reduced": Decimal("0.05"),
    "zero": Decimal("0.00"),
}
CENT = Decimal("0.01")


class ParseError(ValueError):
    """A line in one of the data files breaks a rule."""

    def __init__(self, line: int, reason: str):
        self.line = line
        self.reason = reason
        super().__init__("line {}: {}".format(line, reason))


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]


def iter_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, content) for every non-blank, non-comment line.

    Lines end at LF or CRLF only; a lone CR stays in the content.
    """
    if text.startswith("﻿"):
        text = text[1:]
    if text == "":
        return
    pieces = text.split("\n")
    if pieces and pieces[-1] == "":
        pieces.pop()
    for number, raw in enumerate(pieces, start=1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        stripped = raw.strip(WS)
        if stripped == "" or stripped.startswith("#"):
            continue
        yield number, raw


def parse_date(value: str):
    """Return a datetime.date for a strict YYYY-MM-DD string, or None."""
    m = DATE_RE.match(value)
    if not m:
        return None
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None


def is_sku(value: str) -> bool:
    return bool(SKU_RE.match(value))


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog: Dict[str, Product] = {}
    for n, raw in iter_lines(text):
        fields = [f.strip(WS) for f in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(n, "expected 4 or 5 fields separated by '|', found {}".format(len(fields)))
        sku, name, price, reorder = fields[:4]
        if not is_sku(sku):
            raise ParseError(n, "bad SKU {!r}".format(sku))
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(n, "duplicate SKU {}".format(sku))
        if name == "":
            raise ParseError(n, "empty name")
        if not PRICE_RE.match(price):
            raise ParseError(n, "bad price {!r}".format(price))
        value = Decimal(price).quantize(CENT)
        if value < CENT:
            raise ParseError(n, "price must be at least 0.01")
        if not WHOLE_RE.match(reorder):
            raise ParseError(n, "bad reorder level {!r}".format(reorder))
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(n, "bad tax {!r} (standard, reduced or zero)".format(fields[4]))
        catalog[sku] = Product(sku, name, value, int(reorder), tax)
    return catalog


def _parse_movement_lines(text: str, catalog) -> List[Tuple[int, Movement]]:
    result = []
    for n, raw in iter_lines(text):
        parts = SEP_RE.split(raw.strip(WS), maxsplit=3)
        if len(parts) < 3:
            raise ParseError(n, "expected DATE SKU QUANTITY [NOTE]")
        date_s, sku, qty = parts[0], parts[1], parts[2]
        note = parts[3].strip(WS) if len(parts) == 4 else ""
        date = parse_date(date_s)
        if date is None:
            raise ParseError(n, "bad date {!r}".format(date_s))
        if not is_sku(sku):
            raise ParseError(n, "bad SKU {!r}".format(sku))
        sku = sku.upper()
        if sku not in catalog:
            raise ParseError(n, "unknown SKU {}".format(sku))
        if not SIGNED_RE.match(qty):
            raise ParseError(n, "bad quantity {!r}".format(qty))
        q = int(qty)
        if q == 0:
            raise ParseError(n, "quantity may not be zero")
        result.append((n, Movement(date, sku, q, note)))
    return result


def counting_order(movements):
    """Return movements sorted by date, keeping file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def find_negative(numbered: List[Tuple[int, Movement]]):
    """Return (index, line number) of the first movement taking stock below zero, or None."""
    order = sorted(range(len(numbered)), key=lambda i: numbered[i][1].date)
    balance: Dict[str, int] = {}
    for i in order:
        n, m = numbered[i]
        balance[m.sku] = balance.get(m.sku, 0) + m.quantity
        if balance[m.sku] < 0:
            return i, n
    return None


def parse_movements(text: str, catalog) -> List[Movement]:
    numbered = _parse_movement_lines(text, catalog)
    bad = find_negative(numbered)
    if bad is not None:
        i, n = bad
        raise ParseError(n, "stock of {} would go below zero".format(numbered[i][1].sku))
    return [m for _, m in numbered]


def parse_orders(text: str, catalog) -> List[Order]:
    orders: List[Order] = []
    seen = set()
    for n, raw in iter_lines(text):
        parts = SEP_RE.split(raw.strip(WS))
        if len(parts) != 4:
            raise ParseError(n, "expected ORDER DATE CUSTOMER LINES")
        oid, date_s, customer, lines_s = parts
        if not ORDER_RE.match(oid):
            raise ParseError(n, "bad order number {!r}".format(oid))
        oid = oid.upper()
        if oid in seen:
            raise ParseError(n, "duplicate order {}".format(oid))
        date = parse_date(date_s)
        if date is None:
            raise ParseError(n, "bad date {!r}".format(date_s))
        lines: List[Tuple[str, int]] = []
        skus = set()
        for pair in lines_s.split(","):
            m = ORDER_LINE_RE.match(pair)
            if not m:
                raise ParseError(n, "bad order line {!r} (expected SKU*QUANTITY)".format(pair))
            sku = m.group(1).upper()
            qty = int(m.group(2))
            if qty < 1:
                raise ParseError(n, "quantity must be at least 1 in {!r}".format(pair))
            if sku not in catalog:
                raise ParseError(n, "unknown SKU {}".format(sku))
            if sku in skus:
                raise ParseError(n, "SKU {} appears twice in order {}".format(sku, oid))
            skus.add(sku)
            lines.append((sku, qty))
        seen.add(oid)
        orders.append(Order(oid, date, customer, lines))
    return orders

