def stock_levels(catalog, movements) -> Dict[str, int]:
    """Return SKU -> quantity on the shelf for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        levels[m.sku] = levels.get(m.sku, 0) + m.quantity
    return levels


