        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements) -> List[tuple]:
    """Return (movement, balance) pairs for one SKU, in counting order."""
    rows = []
    balance = 0
    for m in counting_order(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        rows.append((m, balance))
    return rows


def available_on(sku: str, movements, date) -> int:
    """How many of SKU can leave the shelf on DATE without any balance going negative."""
    ordered = [m for m in counting_order(movements) if m.sku == sku]
    balance = sum(m.quantity for m in ordered if m.date <= date)
