"""Order pricing: volume discounts, order discount allocation and tax."""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import List

from .parsing import TAX_RATES

CENT = Decimal("0.01")
ZERO = Decimal("0.00")


def money(value) -> Decimal:
    """Round half up to the penny; never return a negative zero."""
    d = Decimal(value).quantize(CENT, rounding=ROUND_HALF_UP)
    if d == 0:
        return ZERO
    return d


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def volume_rate(quantity: int) -> Decimal:
    if quantity >= 50:
        return Decimal("0.10")
    if quantity >= 10:
        return Decimal("0.05")
    return Decimal("0")


def allocate(pennies: int, weights: List[int]) -> List[int]:
    """Share PENNIES over WEIGHTS by the largest-remainder method (earlier wins ties)."""
    total = sum(weights)
    if pennies == 0 or total == 0:
        return [0] * len(weights)
    shares = []
    remainders = []
    for w in weights:
        q, r = divmod(pennies * w, total)
        shares.append(q)
        remainders.append(r)
    left = pennies - sum(shares)
    for i in sorted(range(len(weights)), key=lambda i: (-remainders[i], i))[:left]:
        shares[i] += 1
    return shares


def price_order(order, catalog) -> Quote:
    """Price ORDER (anything with .lines of (sku, quantity)) against CATALOG."""
    lines = []
    for sku, quantity in order.lines:
        product = catalog[sku]
        unit = money(product.price)
        gross = money(unit * quantity)
        disc = money(gross * volume_rate(quantity))
        net = money(gross - disc)
        lines.append(QuoteLine(sku, quantity, unit, gross, money(-disc), net))
    subtotal = money(sum((l.net for l in lines), ZERO))
    order_disc = money(subtotal * Decimal("0.03")) if subtotal >= Decimal("500.00") else ZERO
    shares = allocate(int(order_disc * 100), [int(l.net * 100) for l in lines])
    tax = ZERO
    for line, share in zip(lines, shares):
        taxable = line.net - Decimal(share) / 100
        tax += money(taxable * TAX_RATES[catalog[line.sku].tax])
    tax = money(tax)
    total = money(subtotal - order_disc + tax)
    return Quote(lines, subtotal, money(-order_disc), tax, total)
