        if parse_date(args[1]) is None:
            raise usage("bad date {!r} (YYYY-MM-DD)".format(args[1]))


def _write_stdout(text: str) -> None:
    buffer = getattr(sys.stdout, "buffer", None)
    if buffer is not None:
        sys.stdout.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        sys.stdout.write(text)
        sys.stdout.flush()


def _silence_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        os.close(devnull)
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        command, args, opts, directory = parse_args(list(argv))
        _validate_dates(command, args)
        files = Files(directory)
        output = HANDLERS[command](files, args, opts)
    except Failure as exc:
        sys.stderr.write("stockroom: {}\n".format(exc.message))
        return exc.code
