import csv
import io
import json
import os
import sys
from typing import List, Optional

from .orders import order_status, shipped_quantities
from .parsing import (
    ORDER_RE,
    WHOLE_RE,
    Movement,
    Order,
    ParseError,
    _parse_movement_lines,
    find_negative,
    is_sku,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
)
from .pricing import price_order
from .stock import available_on, buy_quantity, history, status, stock_levels

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed options, allowed positional counts)
COMMANDS = {
    "stock": ({"--json"}, (0,)),
    "low": ({"--json"}, (0,)),
    "history": ({"--json"}, (1,)),
    "receive": (None, (3, 4)),
    "ship": (None, (3, 4)),
    "quote": ({"--json"}, (1,)),
    "fulfil": (None, (2,)),
    "invoice": ({"--json"}, (1,)),
    "report": ({"--format"}, (0,)),
}
FORMATS = ("text", "csv", "json")


class Failure(Exception):
    """Stop with an exit status and a message for standard error."""

    def __init__(self, code: int, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


def usage(message: str) -> Failure:
    return Failure(2, message)


def refuse(message: str) -> Failure:
    return Failure(1, message)


# ---------------------------------------------------------------- command line


def parse_args(argv: List[str]):
    """Return (command, positionals, options, directory) or raise Failure(2)."""
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage("--dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1
    if directory == "":
        raise usage("--dir needs a value")

    command_at = None
    for j, arg in enumerate(rest):
        if not (arg.startswith("-") and arg != "-"):
            command_at = j
            break
    if command_at is None:
        if rest:
            raise usage("unknown option {}".format(rest[0]))
        raise usage("no command given")
    command = rest[command_at]
    if command not in COMMANDS:
        raise usage("unknown command {!r}".format(command))
    allowed, counts = COMMANDS[command]
    before = rest[:command_at]
    after = rest[command_at + 1:]

    options = {}
    positionals = []
    if allowed is None:
        if before:
            raise usage("unknown option {}".format(before[0]))
        positionals = after
    else:
        args = before + after
        k = 0
        while k < len(args):
            arg = args[k]
            if arg.startswith("-") and arg != "-":
                name, eq, value = arg.partition("=")
                if name not in allowed:
                    raise usage("unknown option {}".format(arg))
                if name == "--json":
                    if eq:
                        raise usage("--json takes no value")
                    options["json"] = True
                elif name == "--format":
                    if not eq:
                        if k + 1 >= len(args):
                            raise usage("--format needs a value")
                        k += 1
                        value = args[k]
                    if value not in FORMATS:
                        raise usage("bad --format value {!r} (text, csv or json)".format(value))
                    options["format"] = value
            else:
                positionals.append(arg)
            k += 1

    if len(positionals) not in counts:
        raise usage("wrong number of arguments for {}".format(command))
    return command, positionals, options, directory


# ---------------------------------------------------------------- files


class Files:
    def __init__(self, directory: str):
        if not os.path.isdir(directory):
            raise usage("{}: no such folder".format(directory))
        self.directory = directory

    def path(self, name: str) -> str:
        return os.path.join(self.directory, name)

    def read_bytes(self, name: str, required: bool) -> bytes:
        try:
            with open(self.path(name), "rb") as fh:
                return fh.read()
        except FileNotFoundError:
            if required:
                raise usage("{}: file not found".format(name))
            return b""
        except OSError as exc:
            raise usage("{}: cannot read: {}".format(name, exc.strerror or exc))

    def read_text(self, name: str, required: bool = False) -> str:
        data = self.read_bytes(name, required)
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise usage("{}: not valid UTF-8 (byte {})".format(name, exc.start))

    def parsed(self, name: str, parse, *args):
        text = self.read_text(name, required=(name == CATALOG))
        try:
            return parse(text, *args)
        except ParseError as exc:
            raise refuse("{}: {}".format(name, exc))

    def catalog(self):
        return self.parsed(CATALOG, parse_catalog)

    def movements(self, catalog):
        return self.parsed(MOVEMENTS, parse_movements, catalog)

    def orders(self, catalog):
        return self.parsed(ORDERS, parse_orders, catalog)

    def append_lines(self, lines: List[str]) -> None:
        path = self.path(MOVEMENTS)
        existing = self.read_bytes(MOVEMENTS, required=False)
        prefix = "\n" if existing and not existing.endswith(b"\n") else ""
        payload = (prefix + "".join(line + "\n" for line in lines)).encode("utf-8")
        try:
            with open(path, "ab") as fh:
                fh.write(payload)
        except OSError as exc:
            raise usage("{}: cannot write: {}".format(MOVEMENTS, exc.strerror or exc))


# ---------------------------------------------------------------- formatting


def amount(d) -> str:
    return "{:.2f}".format(d)


def signed(q: int) -> str:
    return "{:+d}".format(q)


def movement_line(m: Movement) -> str:
    text = "{} {} {}".format(m.date.isoformat(), m.sku, signed(m.quantity))
    return text + (" " + m.note if m.note else "")


def as_json(value) -> str:
    return json.dumps(value, ensure_ascii=False, indent=2) + "\n"


def as_lines(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def find_order(orders, wanted: str) -> Order:
    key = wanted.upper()
    if ORDER_RE.match(key):
        for order in orders:
            if order.id == key:
                return order
    raise refuse("{}: unknown order {}".format(ORDERS, wanted))


def quote_output(header: str, order: Order, quote, use_json: bool) -> str:
    if use_json:
        return as_json({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": amount(l.unit),
                    "gross": amount(l.gross),
                    "discount": amount(l.discount),
                    "net": amount(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": amount(quote.subtotal),
            "order_discount": amount(quote.order_discount),
            "tax": amount(quote.tax),
            "total": amount(quote.total),
        })
    out = [header]
    for l in quote.lines:
        out.append("{} {} {} {} {} {}".format(
            l.sku, l.quantity, amount(l.unit), amount(l.gross), amount(l.discount), amount(l.net)))
    out.append("subtotal " + amount(quote.subtotal))
    out.append("order discount " + amount(quote.order_discount))
    out.append("tax " + amount(quote.tax))
    out.append("total " + amount(quote.total))
    return as_lines(out)


def order_header(order: Order) -> str:
    return "{} {} {}".format(order.id, order.date.isoformat(), order.customer)


def shipped_order(order: Order, shipped: List[int]) -> Order:
    lines = [(sku, s) for (sku, _), s in zip(order.lines, shipped) if s > 0]
    return Order(order.id, order.date, order.customer, lines)


# ---------------------------------------------------------------- commands


def cmd_stock(files, args, opts):
    catalog = files.catalog()
    levels = stock_levels(catalog, files.movements(catalog))
    rows = []
    for sku in sorted(catalog):
        p = catalog[sku]
        rows.append({"sku": sku, "name": p.name, "onhand": levels[sku], "status": status(levels[sku], p.reorder)})
    if opts.get("json"):
        return as_json(rows)
    return as_lines("{} {} {} {}".format(r["sku"], r["onhand"], r["status"], r["name"]) for r in rows)


def cmd_low(files, args, opts):
    catalog = files.catalog()
    levels = stock_levels(catalog, files.movements(catalog))
    rows = []
    for sku in sorted(catalog):
        p = catalog[sku]
        onhand = levels[sku]
        if status(onhand, p.reorder) in ("low", "out"):
            rows.append({"sku": sku, "onhand": onhand, "reorder": p.reorder, "buy": buy_quantity(onhand, p.reorder)})
    if opts.get("json"):
        return as_json(rows)
    return as_lines("{} {} {} {}".format(r["sku"], r["onhand"], r["reorder"], r["buy"]) for r in rows)


def cmd_history(files, args, opts):
    catalog = files.catalog()
    movements = files.movements(catalog)
    sku = args[0].upper()
    if not is_sku(sku) or sku not in catalog:
        raise refuse("{}: unknown SKU {}".format(CATALOG, args[0]))
    rows = [
        {"date": m.date.isoformat(), "delta": signed(m.quantity), "balance": bal, "note": m.note}
        for m, bal in history(sku, movements)
    ]
    if opts.get("json"):
        return as_json(rows)
    out = []
    for r in rows:
        line = "{} {} {}".format(r["date"], r["delta"], r["balance"])
        out.append(line + (" " + r["note"] if r["note"] else ""))
    return as_lines(out)


def _move(files, args, sign: int):
    date = parse_date(args[0])
    catalog = files.catalog()
    movements_text = files.read_text(MOVEMENTS)
    try:
        numbered = _parse_movement_lines(movements_text, catalog)
        bad = find_negative(numbered)
        if bad is not None:
            raise ParseError(bad[1], "stock of {} would go below zero".format(numbered[bad[0]][1].sku))
    except ParseError as exc:
        raise refuse("{}: {}".format(MOVEMENTS, exc))
    sku, qty = args[1], args[2]
    if not is_sku(sku) or sku.upper() not in catalog:
        raise refuse("{}: unknown SKU {}".format(CATALOG, sku))
    sku = sku.upper()
    if not WHOLE_RE.match(qty) or int(qty) < 1:
        raise refuse("bad quantity {!r}: a whole number of one or more is needed".format(qty))
    note = args[3] if len(args) == 4 else ""
    if "\n" in note or "\r" in note:
        raise refuse("a note may not contain a line break")
    note = note.strip(" \t")
    movement = Movement(date, sku, sign * int(qty), note)
    candidate = numbered + [(0, movement)]
    if find_negative(candidate) is not None:
        raise refuse("{}: refused: stock of {} would go below zero".format(MOVEMENTS, sku))
    line = movement_line(movement)
    files.append_lines([line])
    return line + "\n"


def cmd_receive(files, args, opts):
    return _move(files, args, +1)


def cmd_ship(files, args, opts):
    return _move(files, args, -1)


def cmd_quote(files, args, opts):
    catalog = files.catalog()
    order = find_order(files.orders(catalog), args[0])
    return quote_output(order_header(order), order, price_order(order, catalog), opts.get("json"))


def cmd_fulfil(files, args, opts):
    date = parse_date(args[1])
    catalog = files.catalog()
    movements = files.movements(catalog)
    order = find_order(files.orders(catalog), args[0])
    if date < order.date:
        raise refuse("{}: date {} is before the order date {}".format(order.id, date.isoformat(), order.date.isoformat()))
    shipped = shipped_quantities(order, movements)
    note = "order {}".format(order.id)
    new_lines = []
    out = []
    after = []
    for (sku, qty), sent in zip(order.lines, shipped):
        owed = qty - sent
        n = max(0, min(owed, available_on(sku, movements, date)))
        if n > 0:
            new_lines.append(movement_line(Movement(date, sku, -n, note)))
        out.append("{} shipped {} backordered {}".format(sku, n, owed - n))
        after.append(sent + n)
    out.append("status " + order_status(order, after))
    if new_lines:
        files.append_lines(new_lines)
    return as_lines(out)


def cmd_invoice(files, args, opts):
    catalog = files.catalog()
    movements = files.movements(catalog)
    order = find_order(files.orders(catalog), args[0])
    shipped = shipped_quantities(order, movements)
    if not any(shipped):
        raise refuse("{}: nothing shipped yet for {}".format(MOVEMENTS, order.id))
    part = shipped_order(order, shipped)
    return quote_output("invoice " + order_header(order), order, price_order(part, catalog), opts.get("json"))


def _order_key(order: Order):
    return (order.date, int(order.id[3:]), order.id)


def cmd_report(files, args, opts):
    catalog = files.catalog()
    movements = files.movements(catalog)
    orders = files.orders(catalog)
    rows = []
    for order in sorted(orders, key=_order_key):
        shipped = shipped_quantities(order, movements)
        quoted = price_order(order, catalog).total
        invoiced = price_order(shipped_order(order, shipped), catalog).total if any(shipped) else None
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped),
            "quoted": amount(quoted),
            "invoiced": amount(invoiced) if invoiced is not None else "0.00",
        })
    fmt = opts.get("format", "text")
    if fmt == "json":
        return as_json(rows)
    if fmt == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer.writerow(keys)
        for r in rows:
            writer.writerow([r[k] for k in keys])
        return buf.getvalue()
    return as_lines(
        "{} {} {} {} {}/{} {} {}".format(
            r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_receive,
    "ship": cmd_ship,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ---------------------------------------------------------------- entry point


def _validate_dates(command: str, args: List[str]) -> None:
    if command in ("receive", "ship"):
        if parse_date(args[0]) is None:
            raise usage("bad date {!r} (YYYY-MM-DD)".format(args[0]))
    elif command == "fulfil":
        if parse_date(args[1]) is None:
            raise usage("bad date {!r} (YYYY-MM-DD)".format(args[1]))


def _write_stdout(text: str) -> None:
    buffer = getattr(sys.stdout, "buffer", None)
    if buffer is not None:
        sys.stdout.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        sys.stdout.write(text)
        sys.stdout.flush()


def _silence_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        os.close(devnull)
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        command, args, opts, directory = parse_args(list(argv))
        _validate_dates(command, args)
        files = Files(directory)
        output = HANDLERS[command](files, args, opts)
    except Failure as exc:
        sys.stderr.write("stockroom: {}\n".format(exc.message))
        return exc.code
    try:
        _write_stdout(output)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    return 0


if __name__ == "__main__":
    sys.exit(main())

