import contextlib
import io
import os
import sys
import tempfile

SRC = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "src")
if SRC not in sys.path:
    sys.path.insert(0, SRC)

from stockroom import cli  # noqa: E402

CATALOG = (
    "# SKU   | name            | price | reorder | tax\n"
    "AB-100 | Garden gnome     | 12.50 | 5       | standard\n"
    "cd-205 | Seed packet, mix | 1.99  | 40      | reduced\n"
    "EF-310 | Gift voucher     | 25.00 | 0\n"
)
MOVEMENTS = (
    "2024-03-01 AB-100 +20 first delivery\n"
    "2024-03-04 ab-100 -3 order SO-1001\n"
    "2024-03-05 CD-205 40\n"
)
ORDERS = (
    "SO-1001 2024-03-03 acme AB-100*12,CD-205*3\n"
    "SO-1002 2024-03-09 Bea ab-100*2\n"
)


class Shop:
    """A temporary shop folder."""

    def __init__(self, catalog=CATALOG, movements=MOVEMENTS, orders=ORDERS):
        self._tmp = tempfile.TemporaryDirectory()
        self.dir = self._tmp.name
        for name, content in (("catalog.txt", catalog), ("movements.txt", movements), ("orders.txt", orders)):
            if content is not None:
                self.write(name, content)

    def path(self, name):
        return os.path.join(self.dir, name)

    def write(self, name, content):
        data = content.encode("utf-8") if isinstance(content, str) else content
        with open(self.path(name), "wb") as fh:
            fh.write(data)

    def read(self, name):
        with open(self.path(name), "rb") as fh:
            return fh.read()

    def run(self, *argv):
        return run(["--dir", self.dir] + list(argv))

    def close(self):
        self._tmp.cleanup()


def run(argv):
    """Run the CLI in-process; return (exit code, stdout, stderr)."""
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = cli.main(argv)
    return code, out.getvalue(), err.getvalue()
